SELECT DISTINCT text
FROM cards
WHERE name = 'Benalish Knight';

SELECT COUNT(DISTINCT name) AS cards
FROM cards
WHERE ',' || COALESCE(promoTypes, '') || ',' LIKE '%,release,%';

SELECT ROUND(
    100.0 * COUNT(*) FILTER (
        WHERE NOT EXISTS (
            SELECT 1
            FROM "member" m
            WHERE m.link_to_major = major.major_id
        )
    ) / NULLIF(COUNT(*), 0),
    2
) AS percentage
FROM major;

SELECT ROUND(
    100.0 * SUM(CASE WHEN CAST(strftime('%Y', Birthday) AS INTEGER) >= 1960 THEN 1 ELSE 0 END) / COUNT(*),
    1
) AS percentage
FROM Patient
WHERE LOWER(Diagnosis) LIKE '%psoriatic arthritis%';

SELECT ROUND(
    100.0 * SUM(CASE WHEN Diagnosis LIKE 'SLE%' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS percentage
FROM Examination
WHERE Thrombosis > 0;

SELECT ROUND(
    100.0 * SUM(
        CASE WHEN NOT EXISTS (
            SELECT 1
            FROM atom a
            WHERE a.molecule_id = m.molecule_id
              AND a.element = 'F'
        ) THEN 1 ELSE 0 END
    ) / COUNT(*),
    2
) AS percentage
FROM molecule m
WHERE m.label = '+';
